using Azure;
using Azure.AI.Vision.ImageAnalysis;

var client = new ImageAnalysisClient(
    new Uri("https://my-vision-service.cognitiveservices.azure.com/"),
    new AzureKeyCredential("my-api-key")
);

Uri imageUri = new Uri("https://example.com/photo.jpg");

ImageAnalysisResult result = await client.AnalyzeAsync(
    imageUri,
    VisualFeatures.Tags | VisualFeatures.Caption | VisualFeatures.Objects,
    new ImageAnalysisOptions { GenderNeutralCaption = true });

Console.WriteLine("Caption: " + result.Value.Caption.Text);
foreach (var tag in result.Value.Tags.Values)
{
    Console.WriteLine("Tag: " + tag.Name + " (" + tag.Confidence + ")");
}

using Azure;
using Azure.AI.Translation.Text;

var translator = new TextTranslationClient(
    new Uri("https://api.cognitive.microsofttranslator.com/"),
    new AzureKeyCredential("my-api-key")
);

Response<IReadOnlyList<TranslatedText>> response =
    await translator.TranslateAsync(
        new[] { "Hello, how are you?" },
        "fr",
        "en");

foreach (var translation in response.Value)
{
    Console.WriteLine("Translated: " + translation.Text);
}
